mapper.select:
SELECT drug_name, drug_name_chinese, drug_class, rs_id, chr, position, ref, calling, evidence, type, gene, phenotype, translation, cancer_type, allele_info1, allele1, trans1, tox1, eff1, allele_info2, allele2, trans2, tox2, eff2, allele_info3, allele3, trans3, tox3, eff3, PMID FROM chemical_data2
(chr = #{item.chr} and position = #{item.position}
and (
allele1 = #{item.allele} or allele2 = #{item.allele} or allele3 = #{item.allele}
or allele1 = #{item.allele_reverse} or allele2 = #{item.allele_reverse} or allele3 = #{item.allele_reverse}
) )

SELECT
    cf.chr,
    cf.pos AS position,
    cf.allele
FROM
    chem_file cf
        JOIN omics.data_file_status dfs ON cf.file_id = dfs.file_id
WHERE
    dfs.subbarcode = #{subbarcode}

  AND dfs.analysis_date = #{analysis_date}

  AND dfs.product_name = #{product_name}

  AND dfs.file_type = 'Chem'
  AND dfs.STATUS = 'Loaded';
